function simulateFrame(state) {
  const ctx = {
    fillRect: () => {},
    arc: () => {},
    fillText: () => {},
    beginPath: () => {},
    fill: () => {},
  };
  frame(ctx, state);
}

test('brick collision: bounce off bottom face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball moving UP, hits the bottom of the brick
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 2, r: 7, vx: 0, vy: UP };
  // Force collision by moving it into the brick slightly
  state.ball.y -= 4; 
  simulateFrame(state);
  assert.equal(state.ball.vy, DOWN, 'should bounce down');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h, 'should be pushed out to bottom');
});

test('brick collision: bounce off top face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball moving DOWN, hits the top of the brick
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 2, r: 7, vx: 0, vy: DOWN };
  state.ball.y += 4;
  simulateFrame(state);
  assert.equal(state.ball.vy, UP, 'should bounce up');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'should be pushed out to top');
});

test('brick collision: bounce off left face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball moving RIGHT, hits the left of the brick
  state.ball = { x: brick.x - 2, y: brick.y + brick.h / 2, r: 7, vx: RIGHT * 100, vy: 0 };
  state.ball.x += 4;
  simulateFrame(state);
  assert.equal(state.ball.vx, LEFT * 100, 'should bounce left'); // Wait, vx should flip to LEFT
  // Wait, if it hits the left face, vx should become negative.
  // Let me check: vx = RIGHT * 100. Flip means vx = LEFT * 100. Correct.
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'should be pushed out to left');
});

test('brick collision: bounce off right face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball moving LEFT, hits the right of the brick
  state.ball = { x: brick.x + brick.w + 2, y: brick.y + brick.h / 2, r: 7, vx: LEFT * 100, vy: 0 };
  state.ball.x -= 4;
  simulateFrame(state);
  assert.equal(state.ball.vx, RIGHT * 100, 'should bounce right');
  assert.ok(state.ball.x - state.ball.r >= brick.x + brick.w, 'should be pushed out to right');
});

test('brick collision: bounce off corner (diagonal)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball moving DOWN-RIGHT, hits the top-left corner
  state.ball = { x: brick.x - 2, y: brick.y - 2, r: 7, vx: 100, vy: 100 };
  state.ball.x += 2;
  state.ball.y += 2;
  simulateFrame(state);
  assert.equal(state.ball.vx, LEFT * 100, 'vx should flip');
  assert.equal(state.ball.vy, UP * 100, 'vy should flip'); // Wait, vy was 100, should become -100.
});

test('brick collision: no sticky bounce (re-collision)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 2, r: 7, vx: 0, vy: UP };
  state.ball.y -= 4;
  simulateFrame(state); // first hit: bounce DOWN and push out
  const vyAfterFirstHit = state.ball.vy;
  const yAfterFirstHit = state.ball.y;

  // Simulate another frame without moving the ball, it should not bounce again 
  // because it was pushed out.
  simulateFrame(state);
  assert.equal(state.ball.vy, vyAfterFirstHit, 'should not bounce again if already pushed out');
  assert.equal(state.ball.y, yAfterFirstHit, 'should not be pushed further');
});

test('brick collision: tunnelling (high speed)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball at level 6 speed: ~710 px/s.
  // In 0.05s, it moves 35.5 px.
  // If brick is 20px high and gap is 8px.
  // If ball.y is just above the brick, and next frame it's just below.
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 10, r: 7, vx: 0, vy: 700 };
  // Instead of step(), we manually move it to skip the brick
  state.ball.y += 40; // now at brick.y + 30,’ which is below brick.y + brick.h (20)

  // We need a way to tell frame() about the previous position to detect tunnelling.
  // Currently frame() only has state.ball.
  // This test will FAIL until we implement CCD.
  simulateFrame(state);
  assert.ok(!brick.alive, 'brick should be destroyed even if ball tunneled through');
});

