// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  frame,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

function belowField() {
  return 500;
}

function simulateFrame(state) {
  const ctx = {
    fillRect: () => {},
    arc: () => {},
    fillText: () => {},
    beginPath: () => {},
    fill: () => {},
  };
  frame(ctx, state);
}

test('brick collision: bounce off bottom face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 2, r: 7, vx: 0, vy: -1 };
  state.ball.y -= 4; 
  simulateFrame(state);
  assert.equal(state.ball.vy, 1, 'should bounce down');
  assert.ok(state.ball.y - state.ball.r >= brick.y + brick.h, 'should be pushed out to bottom');
});

test('brick collision: bounce off top face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 2, r: 7, vx: 0, vy: 1 };
  state.ball.y += 4;
  simulateFrame(state);
  assert.equal(state.ball.vy, -1, 'should bounce up');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'should be pushed out to top');
});

test('brick collision: bounce off left face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x - 2, y: brick.y + brick.h / 2, r: 7, vx: 100, vy: 0 };
  state.ball.x += 4;
  simulateFrame(state);
  assert.equal(state.ball.vx, -100, 'should bounce left'); 
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'should be pushed out to left');
});

test('brick collision: bounce off right face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x + brick.w + 2, y: brick.y + brick.h / 2, r: 7, vx: -100, vy: 0 };
  state.ball.x -= 4;
  simulateFrame(state);
  assert.equal(state.ball.vx, 100, 'should bounce right');
  assert.ok(state.ball.x - state.ball.r >= brick.x + brick.w, 'should be pushed out to right');
});

test('brick collision: bounce off corner (diagonal)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x - 2, y: brick.y - 2, r: 7, vx: 100, vy: 100 };
  state.ball.x += 2;
  state.ball.y += 2;
  simulateFrame(state);
  assert.equal(state.ball.vx, -100, 'vx should flip');
  assert.equal(state.ball.vy, -100, 'vy should flip');
});

test('brick collision: no sticky bounce (re-collision)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 2, r: 7, vx: 0, vy: -1 };
  state.ball.y -= 4;
  simulateFrame(state);
  const vyAfterFirstHit = state.ball.vy;
  const yAfterFirstHit = state.ball.y;
  simulateFrame(state);
  assert.equal(state.ball.vy, vyAfterFirstHit, 'should not bounce again');
  assert.equal(state.ball.y, yAfterFirstHit, 'should not be pushed further');
});

test('brick collision: tunnelling (high speed)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 10, r: 7, vx: 0, vy: 700 };
  state.ball.y += 40; 
  simulateFrame(state);
  assert.ok(!brick.alive, 'brick should be destroyed even if ball tunneled through');
});

content.thinking:
All the new tests (and some existing ones in `game/sonde.test.js`) are failing. This is expected as we haven't implemented the bounce and CCD yet.

Now I'll implement the fix in `game/neon.js`.

Plan:
1.  Create a `resolveBrickCollision(state, brick)` function.
    - Calculate penetration on each axis.
    - Find the axis with the smallest penetration.
    - Flip the corresponding velocity component.
    - Reposition the ball outside the brick.
2.  Implement Continuous Collision Detection (CCD) to handle tunnelling.
    - I need to know the ball's previous position. I'll add `prevX` and `prevY` to the `ball` object in `createState`.
    - In `step()`, I'll save the current position before updating.
    - In `frame()`, I'll check for intersections between the segment `(prevX, prevY) -> (x, y)` and the brick rectangle.

Actually, if I add `prevX` and `prevY` to the ball, I can detect tunnelling.

Let's update `createState` and `step` first.

Wait, I cannot change the signature of exported functions. Adding properties to the `ball` object in `createState` and updating them in `step` is fine as it doesn't change the signature.

Wait, if I add `prevX`/`prevY` to the ball, it might affect tests that depend on the ball's structure? Probably not.

Actually, instead of adding `prevX`/`prevY` to the ball, I could pass the `dt` and `vx`/`vy` to a `brickHit` function.

Let's see:
`step(state, dt)` moves the ball.
`frame(ctx, state)` handles brick collisions.

If I want CCD, `frame()` needs to know where the ball was *before* `step()`.

The current `frame()` is called after `step()`.

```javascript
    if (state.running) {
      const lost = step(state, dt);
      // ...
    }
    frame(ctx, state);
```

So I should store the previous position in `state.ball` inside `step()`.

Let's implement `resolveBrickCollision`.

```javascript
function resolveBrickCollision(ball, brick) {
  // Ball box: [ball.x - ball.r, ball.x + ball.r] x [ball.y - ball.r, ball.y + ball.r]
  // Brick box: [brick.x, brick.x + brick.w] x [brick.y, brick.y + brick.h]

  const dx1 = ball.x + ball.r - brick.x;
  const dx2 = brick.x + brick.w - (ball.x - ball.r);
  const dy1 = ball.y + ball.r - brick.y;
  const dy2 = brick.y + brick.h - (ball.y - ball.r);

  const penetrationX = Math.min(dx1, dx2);
  const penetrationY = Math.min(dy1, dy2);

  if (penetrationX < penetrationY) {
    // Side hit
    ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx); // This is just flipping sign. Better:
    // Wait, if penetrationX is smaller, it's a side hit.
    // If ball.x + ball.r > brick.x AND ball.x - ball.r < brick.x, it hit the left side.
    // But we already know it collides.
    // If dx1 (ball.x + ball.r - brick.x) is the smallest, it hit the left side.
    // If dx2 (brick.x + brick.w - (ball.x - ball.r)) is the smallest, it hit the right side.

    if (dx1 < dx2) {
      // hit left
      ball.vx = Math.abs(ball.vx); // no, hit left means it was moving RIGHT, now should move LEFT.
      // wait, if it hit the left side of the brick, it must be moving RIGHT. 
      // So vx should become negative.
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
    } else {
      // hit right
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
    }
  } else {
    // Top/bottom hit
    if (dy1 < dy2) {
      // hit top
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
    } else {
      // hit bottom
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
    }
  }
}
```

Wait, I need to be careful with the signs.
`UP` = -1, `DOWN` = 1, `LEFT` = -1, `RIGHT` = 1.

- Hit left face: `vx` should become `LEFT * speed`.
- Hit right face: `vx` should become `RIGHT * speed`.
- Hit top face: `vy` should become `UP * speed`.
- Hit bottom face: `vy` should become `DOWN * speed`.

Wait, if it's a top hit, it should bounce DOWN? No, if it hits the top of the brick, it's moving DOWN, so it should bounce UP.

Let's re-evaluate:
- Ball moving DOWN (`vy > 0`), hits top of brick -> should move UP (`vy < 0`).
- Ball moving UP (`vy < 0`), hits bottom of brick -> should move DOWN (`vy > 0`).
- Ball moving RIGHT (`vx > 0`), hits left of brick -> should move LEFT (`vx < 0`).
- Ball moving LEFT (`vx < 0`), hits right of brick -> should move RIGHT (`vx > 0`).

So:
- `dx1` is distance from ball right edge to brick left edge. If `dx1` is the smallest penetration, it hit the left face. `vx` should become negative.
- `dx2` is distance from ball left edge to brick right edge. If `dx2` is smallest, it hit the right face. `vx` should become positive.
- `dy1` is distance from ball bottom edge to brick top edge. If `dy1` is smallest, it hit the top face. `vy` should become negative.
- `dy2` is distance from ball top edge to brick bottom edge. If `dy2` is smallest, it hit the bottom face. `vy` should become positive.

Now, CCD (tunnelling).
